# R10 -- impute missing vit_plateforme from computed speed (knots)
vit_impute <- run_cross_validation("HUD101107")$R10 |>
  dplyr::filter(reason == "vit_plateforme_manquante") |>
  dplyr::transmute(id_transect, vit_calc_kn = Observed_kmh / 1.852)

transects <- transects |>
  dplyr::left_join(vit_impute, by = "id_transect") |>
  dplyr::mutate(vit_plateforme = dplyr::if_else(
    mission == "HUD101107" & id_transect %in% c(20017, 20048) & is.na(vit_plateforme),
    vit_calc_kn, vit_plateforme
  )) |>
  dplyr::select(-vit_calc_kn)


