# ── MLB090423 | CV_R11 | transects$R11 [2026-03-27 10:40] ──
# R11 -- inspect transects with endpoint issues (mission MLB090423)
transects |> filter(mission == "MLB090423", id_transect %in% c(10259)) |>
  select(mission, id_transect, site, date_heure, longitude, latitude, vit_plateforme) |>
  arrange(id_transect, date_heure)

# R11 -- auto-create missing Debut/Fin rows for transects with exactly one missing endpoint
norm_site <- function(x) {
  y <- tolower(iconv(as.character(x), to = "ASCII//TRANSLIT"))
  dplyr::case_when(
    y %in% c("debut", "start") ~ "debut",
    y %in% c("fin", "end") ~ "fin",
    TRUE ~ NA_character_
  )
}

t_mis <- transects |>
  dplyr::filter(mission == "MLB090423") |>
  dplyr::mutate(site_norm = norm_site(site), dt = suppressWarnings(lubridate::as_datetime(date_heure)))

status <- t_mis |>
  dplyr::group_by(id_transect) |>
  dplyr::summarise(
    n_debut = sum(site_norm == "debut", na.rm = TRUE),
    n_fin = sum(site_norm == "fin", na.rm = TRUE),
    issue = dplyr::case_when(
      n_debut == 0 & n_fin > 0 ~ "missing_debut",
      n_fin == 0 & n_debut > 0 ~ "missing_fin",
      TRUE ~ "other"
    ),
    .groups = "drop"
  ) |>
  dplyr::filter(issue %in% c("missing_debut", "missing_fin"), id_transect %in% c(10259))

first_rows <- t_mis |>
  dplyr::arrange(id_transect, is.na(dt), dt) |>
  dplyr::group_by(id_transect) |>
  dplyr::slice_head(n = 1) |>
  dplyr::ungroup()

last_rows <- t_mis |>
  dplyr::arrange(id_transect, is.na(dt), dplyr::desc(dt)) |>
  dplyr::group_by(id_transect) |>
  dplyr::slice_head(n = 1) |>
  dplyr::ungroup()

rows_debut <- status |>
  dplyr::filter(issue == "missing_debut") |>
  dplyr::inner_join(first_rows, by = "id_transect") |>
  dplyr::mutate(site = "Début")

rows_fin <- status |>
  dplyr::filter(issue == "missing_fin") |>
  dplyr::inner_join(last_rows, by = "id_transect") |>
  dplyr::mutate(site = "Fin")

rows_to_add <- dplyr::bind_rows(rows_debut, rows_fin) |>
  dplyr::select(-n_debut, -n_fin, -issue, -site_norm, -dt)

transects <- dplyr::bind_rows(transects, rows_to_add)


