# ── PER130717 | CV_R4 | observations$R4 [2026-03-27 11:17] ──
# R4 fix: copy _rad into _par where _par is missing, then clear _rad
observations <- observations |>
  mutate(
    tra_par = if_else(mission == "PER130717" &
      (is.na(tra_par) & is.na(dis_par)) & (!is.na(tra_rad) | !is.na(dis_rad)),
      tra_rad, tra_par),
    dis_par = if_else(mission == "PER130717" &
      (is.na(tra_par) & is.na(dis_par)) & (!is.na(tra_rad) | !is.na(dis_rad)),
      dis_rad, dis_par),
    tra_rad = if_else(mission == "PER130717" & !is.na(tra_par), NA_real_, tra_rad),
    dis_rad = if_else(mission == "PER130717" & !is.na(dis_par), NA_real_, dis_rad)
  )

