      code_espece == "mena" ~ "ALHC",
      code_espece == "OCcb" ~ "OCCB",
      code_espece == "oisp" ~ "ALHC",
      code_espece == "pusp" ~ "ALHC",
      TRUE ~ code_espece
    )
  )

# ── TEL110817 | UNKNOWN_CATALOG | observations$activite [2026-03-27 11:30] ──
observations <- observations |>
  mutate(
    activite = case_when(
      activite == "Eau" ~ "EAU",
      activite == "Navire" ~ "NAVIRE",
      TRUE ~ activite
    )
  )

# ── TEL110817 | UNKNOWN_CATALOG | observations$tra_par [2026-03-27 11:31] ──
observations <- observations |>
  mutate(
    tra_par = case_when(
      tra_par == "exterieur" ~ "Exterieur",
      TRUE ~ tra_par
    )
  )

# ── TEL110817 | UNKNOWN_CATALOG | observations$plumage [2026-03-27 11:31] ──
observations <- observations |>
  mutate(
    plumage = case_when(
      plumage == "Forme claire" ~ "Forme Claire",
      TRUE ~ plumage
    )
  )

# ── TEL110817 | OUTSIDE_MISSION_DATES | observations$heure [2026-03-27 11:31] ──
observations <- observations |>
  mutate(
    heure = if_else(
      mission == "TEL110817" &
      (heure < as.POSIXct("2011-08-17 00:00:00") |
       heure > as.POSIXct("2011-08-28 23:59:59")),
      as.POSIXct(paste(as.Date(date), format(heure, "%H:%M:%S")), tz="UTC"),
      heure
    )
  )

# ── TEL110817 | CV_R1 | observations$R1 [2026-03-27 11:32] ──
# R1 -- assign missing id_transect (mission TEL110817)
# Inspect these observation ids and assign manually:
observations |> filter(mission == "TEL110817", id %in% c()) |>
  select(id, date, heure, in_transect, id_transect, code_espece)

# Example fix (replace XX with correct transect id):
# observations <- observations |>
#   mutate(id_transect = if_else(mission == "TEL110817" & id %in% c(), XX, id_transect))


# ── TEL110817 | CV_R4 | observations$R4 [2026-03-27 11:33] ──
# R4 fix: copy _rad into _par where _par is missing, then clear _rad
observations <- observations |>
  mutate(
    tra_par = if_else(mission == "TEL110817" &
      (is.na(tra_par) & is.na(dis_par)) & (!is.na(tra_rad) | !is.na(dis_rad)),
      tra_rad, tra_par),
    dis_par = if_else(mission == "TEL110817" &
      (is.na(tra_par) & is.na(dis_par)) & (!is.na(tra_rad) | !is.na(dis_rad)),
      dis_rad, dis_par),
    tra_rad = if_else(mission == "TEL110817" & !is.na(tra_par), NA_real_, tra_rad),
    dis_rad = if_else(mission == "TEL110817" & !is.na(dis_par), NA_real_, dis_rad)
  )

# ── TEL110817 | CV_R6 | observations$R6 [2026-03-27 11:34] ──
# R6 fix: set snapshot = 'Oui' where activite = VOL (mission TEL110817)
observations <- observations |>
  mutate(
    snapshot = if_else(
      mission == "TEL110817" &
      str_to_upper(str_trim(activite)) == "VOL" &
      str_to_upper(str_trim(snapshot)) != "OUI",
      "Oui", snapshot
    )
  )

# ── TEL110817 | CV_R10 | transects$R10 [2026-03-27 11:34] ──
# R10 -- targeted inspection (mission TEL110817)
transects |> filter(mission == "TEL110817", id_transect %in% c(3, 4, 5, 6, 7, 8, 9, 10, 11, 15, 18, 19, 20, 23, 26, 30, 31, 33, 34, 38)) |>
  select(mission, id_transect, site, date_heure, longitude, latitude, vit_plateforme)

# R10 -- impute missing vit_plateforme from computed speed (knots)
vit_impute <- run_cross_validation("TEL110817")$R10 |>
  dplyr::filter(reason == "vit_plateforme_manquante") |>
  dplyr::transmute(id_transect, vit_calc_kn = Observed_kmh / 1.852)

transects <- transects |>
  dplyr::left_join(vit_impute, by = "id_transect") |>
  dplyr::mutate(vit_plateforme = dplyr::if_else(
    mission == "TEL110817" & id_transect %in% c(4, 5, 7, 8, 9, 10, 11, 15, 18, 19, 23, 26, 30, 31, 34, 38) & is.na(vit_plateforme),
    vit_calc_kn, vit_plateforme
  )) |>
  dplyr::select(-vit_calc_kn)



